except Exception as exc:
    print("TARGETS_ERROR %s" % exc)

try:
    status, body = get("/api/v1/query?" + urllib.parse.urlencode({"query": "node_uname_info"}))
    now = time.time()
    print("QUERY_API status=%s api_status=%s now_epoch=%.3f" % (status, body.get("status"), now))
    results = body.get("data", {}).get("result", [])
    print("NODE_UNAME_RESULT_COUNT %d" % len(results))
